//! Initial bytes shared by the immutable old and recorded-native adapters.
pub const CASES:&[&str]=&["invalid_utf8","splitlines_allow","first_match","hidden_exempt"];
pub fn files(case:&str)->Option<Vec<(String,Vec<u8>)>>{let mut out=vec![("deepquarry.dme".into(),b"// raw cache policy\n".to_vec()),("tools/ci/lint_scopes.toml".into(),b"[lint.cache]\n".to_vec())];match case{
"invalid_utf8"=>{out.push(("code/.hidden/bad.dm".into(),b"var/static/list/a_ca\xffche = list()\r\nvar/list/b_cache = list() // ALLOW(cache/BYTES): this process cache is maintained by the platform adapter\r\n".to_vec()));out.push(("code/valid_replacement.dm".into(),"var/static/list/a_ca\u{fffd}che = list()\nvar/list/plain_cache = list()\n".as_bytes().to_vec()));},
"splitlines_allow"=>out.push(("code/splits.dm".into(),"// ALLOW(cache/SPLIT): this local cache is rebuilt whenever the subsystem reloads\u{0c}var/list/a_cache\nvar/list/b_cache\u{2028}var/list/c_cache\u{85}var/list/d_cache\rvar/list/e_cache\r\n".as_bytes().to_vec())),
"first_match"=>out.push(("code/order.dm".into(),b"var/static/list/typecache_a = list(); var/static/list/real_cache = list()\nvar/static/list/real_cache = list(); var/static/list/typecache_a = list()\nvar/static/list/comments = list() // var/static/list/comment_cache\nGLOBAL_LIST_INIT(global_cache, list())\nvar/global/list/raw_cache\n".to_vec())),
"hidden_exempt"=>{out[1].1=b"[lint.cache]\nexempt_prefixes = [\"code/exempt/\"]\n".to_vec();out.push(("code/.hidden/cache.dm".into(),b"var/list/hidden_cache\n".to_vec()));out.push(("code/exempt/skip.dm".into(),b"var/list/skipped_cache\n".to_vec()));},_=>return None}Some(out)}
